export function toLoadError(error) {
    return error instanceof Error ? error : new Error(String(error));
}
export function shouldCollectLoadErrors(errorHandling) {
    return errorHandling === 'aggregate' || errorHandling === 'return';
}
export function createFailedSource(location, error) {
    return {
        location,
        error: toLoadError(error),
    };
}
